static void draw_giant_damage_fx(void){if(!g.fx)return;nquad=0;SDL_Texture*batch=giantDamageTexture;for(int i=0;i<GIANT_FX_CAPACITY;i++){GiantFX*p=giantFX+i;if(p->life<=0)continue;float t=p->age/p->life,fade=fminf(1,p->age*25)*(1-t),w=p->size,h=w*4/3,alpha=fade*(reducedMotion?.5f:.72f);SDL_FColor colour={1,1,1,alpha};SDL_Texture*texture=giantDamageTexture;float u=(p->cell%4)/4.0f,v=(p->cell/4)/2.0f,uw=.25f,vh=.5f;if(p->kind==0){w*=1+t*1.5f;h=w*4/3;colour=(SDL_FColor){.85f,.85f,.88f,fade*.62f};}else if(p->kind==1){int frame=reducedMotion?p->cell:(p->cell+(int)(p->age*10))%4;u=frame/4.0f;v=0;colour.a=fade*.9f;}else if(p->kind==3||p->kind==4){int blood=p->kind==3;const float*uv=blood?bloodUV[p->cell]:gooUV[p->cell];texture=blood?bloodTexture:gooTexture;u=uv[0];v=uv[1];uw=uv[2];vh=uv[3];h=w*vh*1024/(uw*1536);colour.a=fade*.8f;}else if(p->kind>=5){w*=1+t;h=w*4/3;colour=p->kind==5?(SDL_FColor){.65f,.15f,.24f,fade*.3f}:(SDL_FColor){.18f,.65f,.12f,fade*.3f};}if(texture!=batch){flush(batch);batch=texture;}float y=p->y-(p->kind==1?h*.44f:0);if(p->clip)flush(batch);int first=nquad;quad((p->x-w/2)*3,(y-h/2)*3,w*3,h*3,colour,u,v,uw,vh);if(p->clip){SDL_Vertex source[4];memcpy(source,vertices+first*4,sizeof(source));nquad=first;worm_clip_quad(source);flush(batch);}}flush(batch);}
